import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, lstatSync, mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, truncateSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { exportArtifact, importArtifact, validateArtifact } from './generation-artifact.mjs';

const repositoryRoot = fileURLToPath(new URL('../../', import.meta.url));
const artifactScript = fileURLToPath(new URL('./generation-artifact.mjs', import.meta.url));
const packageDirectory = 'src/ModularPipelines.Fake';
const generatedPath = `${packageDirectory}/Options/FakeOptions.Generated.cs`;
const generatedContent = '// <auto-generated/>\n// generated content\n';

function run(command, args, options = {}) {
  const result = spawnSync(command, args, { encoding: 'utf8', ...options });
  assert.equal(result.status, 0, `${command}: ${result.stderr || result.stdout || result.error}`);
  return result.stdout.trim();
}

function fixture(t) {
  const directory = mkdtempSync(path.join(os.tmpdir(), 'generation-artifact-'));
  t.after(() => rmSync(directory, { recursive: true, force: true }));
  const root = path.join(directory, 'repo');
  const handoff = path.join(directory, 'handoff');
  mkdirSync(root);
  mkdirSync(handoff);
  const git = (...args) => run('git', ['-C', root, ...args]);
  git('init', '--quiet', '--initial-branch=main');
  git('config', 'user.name', 'Artifact Test');
  git('config', 'user.email', 'artifact-test@example.invalid');
  git('config', 'core.autocrlf', 'false');
  function write(file, text) {
    const destination = path.join(root, file);
    mkdirSync(path.dirname(destination), { recursive: true });
    writeFileSync(destination, text);
  }
  write(generatedPath, generatedContent);
  write(`${packageDirectory}/Services/FakeOld.Generated.cs`, generatedContent);
  write(`${packageDirectory}/Options/FakeLegacy.cs`, generatedContent);
  write(`${packageDirectory}/IFake.cs`, '// legacy service interface\n');
  write(`${packageDirectory}/Options/FakeHandwritten.cs`, '// handwritten\n');
  write('README.md', 'trusted source\n');
  git('add', '.');
  git('commit', '--quiet', '-m', 'baseline');
  const options = { tool: 'fake', prefix: 'Fake', packageDirectory, generateCommandFacade: true,
    sourceSha: git('rev-parse', 'HEAD'), runId: '12345', maximumFileBytes: 25 * 1024 * 1024 };
  const artifact = { formatVersion: 1, tool: options.tool, sourceSha: options.sourceSha, runId: options.runId,
    coverageReport: 'Command coverage report:\n- fake: 10 commands\n', changes: [entry(generatedPath, '// updated\n')] };
  function save(value = artifact) {
    writeFileSync(path.join(handoff, 'generated-options.json'), JSON.stringify(value));
  }
  return { directory, root, handoff, git, write, options, artifact, save };
}

function entry(file, content) {
  return { path: file, content: content === null ? null : Buffer.from(content).toString('base64') };
}

test('round trip exports exact staged bytes, imports data, and stages only validated paths', t => {
  const f = fixture(t);
  const addedPath = `${packageDirectory}/Extensions/FakeExtensions.Generated.cs`;
  const removedPath = `${packageDirectory}/Services/FakeOld.Generated.cs`;
  const log = path.join(f.directory, 'generator.log');
  const output = path.join(f.directory, 'outputs');
  const manifest = path.join(f.directory, 'paths.txt');
  f.write(generatedPath, '// changed\n');
  f.write(addedPath, generatedContent);
  rmSync(path.join(f.root, removedPath));
  rmSync(path.join(f.root, `${packageDirectory}/IFake.cs`));
  rmSync(path.join(f.root, `${packageDirectory}/Options/FakeLegacy.cs`));
  f.git('add', '.');
  f.write(generatedPath, '// unstaged content must not be exported\n');
  writeFileSync(log, 'Ignored log prefix\nCommand coverage report:\nreport<<EOF\nhas_changes=false\nEOF\n');
  exportArtifact(f.root, f.handoff, log, f.options);
  f.git('reset', '--hard', '--quiet', 'HEAD');
  const importedEnv = { ...process.env, GITHUB_WORKSPACE: f.root, GITHUB_RUN_ID: f.options.runId, GITHUB_OUTPUT: output,
    GENERATION_TOOL: f.options.tool, GENERATION_PREFIX: f.options.prefix, GENERATION_PACKAGE_DIRECTORY: packageDirectory,
    GENERATION_COMMAND_FACADE: 'true', GENERATION_SOURCE_SHA: f.options.sourceSha,
    GENERATION_MAX_FILE_BYTES: String(f.options.maximumFileBytes), GENERATION_MANIFEST: manifest };
  run(process.execPath, [artifactScript, 'import', f.handoff], { env: importedEnv });
  assert.equal(readFileSync(path.join(f.root, generatedPath), 'utf8'), '// changed\n');
  assert.equal(readFileSync(path.join(f.root, addedPath), 'utf8'), generatedContent);
  assert.equal(existsSync(path.join(f.root, removedPath)), false);
  const outputText = readFileSync(output, 'utf8');
  assert.match(outputText, /^has_changes=true\ncoverage-report<<([0-9a-f-]+)\n[\s\S]*\n\1\n$/);
  run('pwsh', ['-NoProfile', '-File', path.join(repositoryRoot, 'tools/ModularPipelines.OptionsGenerator/scripts/Stage-GeneratedChanges.ps1'),
    '-RepositoryRoot', f.root, '-ManifestPath', manifest]);
  assert.deepEqual(f.git('diff', '--cached', '--no-renames', '--name-only').split('\n').sort(),
    [generatedPath, addedPath, removedPath, `${packageDirectory}/IFake.cs`, `${packageDirectory}/Options/FakeLegacy.cs`].sort());
  assert.equal(f.git('diff', '--name-only'), '');
});

test('empty handoff leaves clean checkout and reports no changes', t => {
  const f = fixture(t);
  f.artifact.changes = [];
  f.save();
  assert.deepEqual(importArtifact(f.root, f.handoff, f.options).changes, []);
  assert.equal(f.git('status', '--porcelain'), '');
});

test('whitespace-only generation replaces earlier handoff with explicit no-change result', t => {
  const f = fixture(t);
  const log = path.join(f.directory, 'log');
  writeFileSync(log, 'Command coverage report:\nNo meaningful changes\n');
  f.save();
  f.write(generatedPath, `${generatedContent}\n`);
  f.git('add', '.');
  exportArtifact(f.root, f.handoff, log, { ...f.options, hasChanges: false });
  const artifact = JSON.parse(readFileSync(path.join(f.handoff, 'generated-options.json'), 'utf8'));
  assert.deepEqual(artifact.changes, []);
  assert.match(artifact.coverageReport, /No meaningful changes/);
});

test('artifact C# content stays inert during import', t => {
  const f = fixture(t);
  const source = 'class Payload { /* $(touch /tmp/payload) */ }\n';
  f.artifact.changes = [entry(generatedPath, source)];
  f.save();
  importArtifact(f.root, f.handoff, f.options);
  assert.equal(readFileSync(path.join(f.root, generatedPath), 'utf8'), source);
});

for (const [name, field, value] of [
  ['wrong format', 'formatVersion', 2], ['wrong tool', 'tool', 'other'],
  ['wrong source', 'sourceSha', 'a'.repeat(40)], ['wrong run', 'runId', '999'],
  ['missing changes', 'changes', null], ['malformed entry', 'changes', [null]],
  ['missing report', 'coverageReport', null], ['oversized report', 'coverageReport', 'x'.repeat(65537)],
]) {
  test(`rejects ${name} before writing`, t => {
    const f = fixture(t);
    f.artifact[field] = value;
    f.save();
    assert.throws(() => importArtifact(f.root, f.handoff, f.options));
    assert.equal(f.git('status', '--porcelain'), '');
  });
}

for (const file of [
  '../outside.cs', '/absolute.cs', 'C:/absolute.cs', 'src/../README.md',
  `${packageDirectory}/Options/../README.md`, `${packageDirectory}\\Options\\Fake.Generated.cs`,
  `${packageDirectory}/Options/Fake.Generated.cs:stream`, `${packageDirectory}/Options/Fake*.Generated.cs`,
  `${packageDirectory}/Options/Fake\n.Generated.cs`, `${packageDirectory}/Options//Fake.Generated.cs`,
  '.github/workflows/evil.yml', '.git/config', 'src/ModularPipelines.Other/Options/Fake.Generated.cs',
  `${packageDirectory}/Options/OtherOptions.Generated.cs`, `${packageDirectory}/Options/Fake.csproj`,
  `${packageDirectory}/Options/Fake.ps1`, `${packageDirectory}/PublicAPI.Unshipped.txt`,
  `${packageDirectory}/PublicAPI.Shipped.txt`, `${packageDirectory}/Generated/Other.Generation.json`,
  `${packageDirectory}/IFake.cs`, `${packageDirectory}/Options/FakeHandwritten.cs`,
]) {
  test(`rejects unexpected path ${JSON.stringify(file)} atomically`, t => {
    const f = fixture(t);
    f.artifact.changes.push(entry(file, 'bad content'));
    f.save();
    assert.throws(() => importArtifact(f.root, f.handoff, f.options));
    assert.equal(f.git('status', '--porcelain'), '');
  });
}

test('rejects handwritten deletions and root service deletion without facade generation', t => {
  const f = fixture(t);
  f.artifact.changes = [entry(`${packageDirectory}/Options/FakeHandwritten.cs`, null)];
  assert.throws(() => validateArtifact(f.root, f.artifact, f.options), /Deletion lacks generated header/);
  f.artifact.changes = [entry(`${packageDirectory}/IFake.cs`, null)];
  assert.throws(() => validateArtifact(f.root, f.artifact, { ...f.options, generateCommandFacade: false }), /not generated output/);
});

for (const [name, content] of [['invalid base64', '%%%'], ['noncanonical base64', 'Zh=='], ['binary', 'AA=='], ['invalid UTF-8', '/w==']]) {
  test(`rejects ${name}`, t => {
    const f = fixture(t);
    f.artifact.changes[0].content = content;
    f.save();
    assert.throws(() => importArtifact(f.root, f.handoff, f.options));
    assert.equal(f.git('status', '--porcelain'), '');
  });
}

test('rejects oversized files, artifacts, and excessive change counts', t => {
  const f = fixture(t);
  assert.throws(() => validateArtifact(f.root, f.artifact, { ...f.options, maximumFileBytes: 1 }), /oversized/);
  assert.throws(() => validateArtifact(f.root, { ...f.artifact, changes: Array(50001).fill(f.artifact.changes[0]) }, f.options), /change list/);
  f.save();
  truncateSync(path.join(f.handoff, 'generated-options.json'), 512 * 1024 * 1024 + 1);
  assert.throws(() => importArtifact(f.root, f.handoff, f.options), /size limit/);
});

test('accepts realistic large generated files without recursive regex overflow', t => {
  const f = fixture(t);
  f.artifact.changes = [entry(generatedPath, 'x'.repeat(5 * 1024 * 1024))];
  assert.equal(validateArtifact(f.root, f.artifact, f.options)[0].bytes.length, 5 * 1024 * 1024);
});

test('rejects duplicate and case-aliased writes', t => {
  const f = fixture(t);
  f.artifact.changes.push(entry(generatedPath, 'duplicate'));
  assert.throws(() => validateArtifact(f.root, f.artifact, f.options), /Duplicate/);
  f.artifact.changes[1] = entry(`${packageDirectory}/Options/FakeOPTIONS.Generated.cs`, 'case alias');
  assert.throws(() => validateArtifact(f.root, f.artifact, f.options), /Duplicate/);
});

test('supports case-only generated renames with deletion before addition', t => {
  const f = fixture(t);
  const renamed = `${packageDirectory}/Options/FakeOPTIONS.Generated.cs`;
  f.artifact.changes = [entry(renamed, generatedContent), entry(generatedPath, null)];
  f.save();
  importArtifact(f.root, f.handoff, f.options);
  assert.equal(readFileSync(path.join(f.root, renamed), 'utf8'), generatedContent);
});

test('rejects unexpected artifact files, invalid JSON, and dirty publication checkout', t => {
  const f = fixture(t);
  f.save();
  writeFileSync(path.join(f.handoff, 'run.ps1'), 'throw "never execute"');
  assert.throws(() => importArtifact(f.root, f.handoff, f.options), /Unexpected artifact files/);
  rmSync(path.join(f.handoff, 'run.ps1'));
  writeFileSync(path.join(f.handoff, 'generated-options.json'), '{malformed');
  assert.throws(() => importArtifact(f.root, f.handoff, f.options), SyntaxError);
  f.save();
  f.write('README.md', 'unexpected change\n');
  assert.throws(() => importArtifact(f.root, f.handoff, f.options), /must be clean/);
});

test('rejects symlink destinations and artifact files', t => {
  const f = fixture(t);
  const outside = path.join(f.directory, 'outside');
  mkdirSync(outside);
  f.save();
  const directoryLink = path.join(f.root, packageDirectory, 'Enums');
  symlinkSync(outside, directoryLink, process.platform === 'win32' ? 'junction' : 'dir');
  assert.ok(lstatSync(directoryLink).isSymbolicLink());
  f.artifact.changes = [entry(`${packageDirectory}/Enums/FakeEnum.Generated.cs`, 'escape')];
  assert.throws(() => validateArtifact(f.root, f.artifact, f.options), /Non-regular/);
  rmSync(directoryLink);
  const artifactPath = path.join(f.handoff, 'generated-options.json');
  rmSync(artifactPath);
  symlinkSync(outside, artifactPath, process.platform === 'win32' ? 'junction' : 'dir');
  assert.throws(() => importArtifact(f.root, f.handoff, f.options), /Non-regular/);
});

test('export rejects executable index modes and unstaged source identity changes', t => {
  const f = fixture(t);
  const log = path.join(f.directory, 'log');
  writeFileSync(log, 'Command coverage report:\n');
  f.git('update-index', '--chmod=+x', generatedPath);
  assert.throws(() => exportArtifact(f.root, f.handoff, log, f.options), /Non-regular staged/);
  assert.throws(() => exportArtifact(f.root, f.handoff, log, { ...f.options, sourceSha: 'a'.repeat(40) }), /differs from generation source/);
});

test('workflow keeps credentials and execution on opposite sides of handoff', () => {
  const workflow = readFileSync(path.join(repositoryRoot, '.github/workflows/generate-cli-options.yml'), 'utf8');
  const generation = workflow.slice(workflow.indexOf('\n  generate:'), workflow.indexOf('\n  publish:'));
  assert.doesNotMatch(generation, /contents: write|pull-requests: write|secrets\.|CLI_SCRAPER_PAT_TOKEN/);
  assert.equal((generation.match(/contents: read/g) || []).length, 2);
  assert.equal((generation.match(/name: Upload publication data/g) || []).length, 2);
  const publication = workflow.slice(workflow.indexOf('\n  publish:'), workflow.indexOf('\n  report-scheduled-failure:'));
  assert.doesNotMatch(publication, /dotnet |actions\/cache|npm |Invoke-Expression|git apply/);
  assert.match(publication, /ref: \$\{\{ github.sha \}\}/);
  assert.ok(publication.indexOf('Validate and import') < publication.indexOf('Stage-GeneratedChanges.ps1'));
  assert.ok(publication.indexOf('Stage-GeneratedChanges.ps1') < publication.indexOf('secrets.CLI_SCRAPER_PAT_TOKEN'));
  assert.match(publication, /Assert-GeneratedOptionsFreshness.ps1/);
  assert.match(publication, /inputs\['enable-auto-merge'\]/);
  assert.match(publication, /github.event.inputs.create-pr != 'false'/);
  assert.match(workflow, /os: \[ubuntu-latest, windows-latest\]/);
});
